586	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
587	        for (Protocol protocol : protocols) {
588	            String prot = protocol.toString();
589	
590	            if (prot.equals("#")) { // allows anchor links
591	                if (isValidAnchor(value)) {
592	                    return true;
593	                } else {
594	                    continue;
595	                }
596	            }
597	
598	            String lc = lowerCase(value);
599	            if (lc.startsWith(prot)
600	                && lc.length() > prot.length()
601	                && lc.charAt(prot.length()) == ':') {
602	                return true;
603	            }
604	        }
605	        return false;
606	    }
