628	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
629	        StringBuilder sb = StringUtil.borrowBuilder();
630	
631	        int pos = 0, length = value.length();
632	        while (pos <= length) {
633	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
634	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
635	            // separators produce empty candidates, which are invalid.
636	            int start = pos, end = pos;
637	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
638	            boolean started = false; // seen non-whitespace content in this candidate
639	            while (end < length) {
640	                char c = value.charAt(end);
641	                if (c == ',') {
642	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
643	                        end++; // comma is part of the URL
