import org.jsoup.safety.Safelist;

public class Check {
    public static void main(String[] args) {
        Safelist sl = Safelist.none().addTags("img").addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
        String[] cases = {
            "<img srcset='jav&#x09;ascript:alert(1) 1x, https://ok.com/a.jpg 2x'>",   // entity-decoded tab inside scheme
            "<img srcset='jav&#x0B;ascript:alert(1) 1x'>",                            // vertical tab (not HTML space)
            "<img srcset='javascript&#x3A;alert(1) 1x'>",                             // entity-decoded colon
            "<img srcset='&#x6A;avascript:alert(1) 1x'>",                             // entity-decoded 'j'
            "<img srcset='%6Aavascript:alert(1) 1x, https://ok.com/a.jpg'>",          // percent-encoded j
            "<img srcset='javascript%3Aalert(1) 1x'>",                                // percent-encoded colon
            "<img srcset='//evil.com/a.jpg 1x'>",                                     // protocol-relative
            "<img srcset='  https://ok.com/a.jpg 1x  ,  javascript:x 2x  '>",         // surrounding whitespace
            "<img srcset='HTTPS://ok.com/a.jpg 1x'>",                                 // case
        };
        for (String h : cases) {
            System.out.println(Jsoup.clean(h, "https://base.com/", sl));
        }
    }
}
